//! The Localization OS ASS suite (`tests/verify_ass_filter.py`, ten cases) ported one to one. Where the Python test
//! drives the LocOS web API and CLI (`pipeline_api_cli`), the Rust case runs the same document through extract,
//! a mock "translation" that keeps every token, and merge, and checks the same output properties.
mod common;
use bilingua_ass::AssFilter;
use bilingua_model::*;
use common::*;

fn ass() -> String {
    [
        "[Script Info]\n",
        "; Script generated by hand\n",
        "Title: The Long Night\n",
        "ScriptType: v4.00+\n",
        "PlayResX: 1920\n",
        "\n",
        "[V4+ Styles]\n",
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, ",
        "Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, ",
        "Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n",
        "Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,",
        "0,0,0,0,100,100,0,0,1,2,2,2,10,10,10,1\n",
        "\n",
        "[Events]\n",
        "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n",
        "Dialogue: 0,0:00:01.00,0:00:04.00,Default,Anna,0,0,0,,Hello, world, how are you?\n",
        "Comment: 0,0:00:01.00,0:00:04.00,Default,,0,0,0,,Do not translate this note\n",
        "Dialogue: 0,0:00:05.00,0:00:07.50,Default,,0,0,0,,",
        "{\\an8}I said {\\i1}no{\\i0}.\\NNever again.\n",
        "Dialogue: 0,0:00:08.00,0:00:09.00,Default,,0,0,0,,{\\pos(400,570)}\n",
        "Dialogue: 1,0:00:10.00,0:00:11.00,Default,,0,0,0,,{\\p1}m 0 0 l 100 0 100 100 0 100{\\p0}\n",
        "Dialogue: 0,0:00:12.00,0:00:13.00,Default,,0,0,0,,Wait\\hfor it\\n... {fix timing}now\\N\n",
    ]
    .concat()
}

const HEAD: &str = "[Events]\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,";

#[test]
fn registered() {
    let f = AssFilter;
    assert_eq!(f.id(), "ass");
    assert!(f.extensions().contains(&"ass") && f.extensions().contains(&"ssa"));
    assert!(f.sniff(ass().as_bytes()));
    assert!(!f.sniff(b"1\n00:00:01,000 --> 00:00:02,000\nHi\n"));
}

#[test]
fn units_and_identity() {
    let data = ass().into_bytes();
    assert_eq!(
        units(&data),
        vec![
            "The Long Night",
            "Hello, world, how are you?",
            "I said ⟦g1⟧no⟦/g1⟧.⟦x2⟧Never again.",
            "Wait⟦x1⟧for it⟦x2⟧... ⟦x3⟧now",
        ]
    );
    assert_identity(&data);
    let crlf = ass().replace('\n', "\r\n").into_bytes();
    assert_identity(&crlf);
    let mut bom = b"\xef\xbb\xbf".to_vec();
    bom.extend_from_slice(&data);
    assert_eq!(units(&bom), units(&data));
    assert_identity(&bom);
    let mixed = b"[Events]\r\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Hi\nComment: x\r\n";
    assert_identity(mixed);
    let no_eol = b"[Events]\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Hi there";
    assert_identity(no_eol);
}

#[test]
fn gate_lines_language() {
    // U+2028 / U+0085 / form feed inside a Text field does not end the line
    let odd = "[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n\
        Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,One two\x0cthree, four\n\
        Dialogue: 0,0:00:03.00,0:00:04.00,Default,,0,0,0,,Keep ⟦x9⟧ as is\n";
    let data = odd.as_bytes();
    assert_eq!(units(data), vec!["One two\x0cthree, four", "Keep ⟦x9⟧ as is"]);
    let out = s(build_locos(data, &[(0, "Eins zwei drei, vier")]));
    assert!(out.contains(",,Eins zwei drei, vier\n") && !out.contains("three"), "{out}");
    // an untouched line keeps literal bracket text byte for byte
    assert!(out.contains("Keep ⟦x9⟧ as is"), "{out}");
    // localized export: libass Language header set, or added after [Script Info]
    let data2 = ass().replace('\n', "\r\n").into_bytes();
    let loc = s(build_localized(&data2, &[], Some("de-DE")));
    assert!(loc.starts_with("[Script Info]\r\nLanguage: de\r\n"), "{}", &loc[..80]);
    assert_eq!(build_localized(&data2, &[], None), data2);
    let with_lang = ass().replace("ScriptType", "Language: en\nScriptType").into_bytes();
    let loc2 = s(build_localized(&with_lang, &[], Some("pt-BR")));
    assert!(loc2.contains("Language: pt\n") && !loc2.contains("Language: en"), "{loc2}");
    assert_eq!(loc2.matches("Language:").count(), 1);
    let loc3 = s(build_localized(&with_lang, &[], Some("fil-PH")));
    assert!(!loc3.contains("Language:"), "a target with no 2-letter code drops the stale header");
}

#[test]
fn translated_round_trip() {
    let data = ass().into_bytes();
    let out = s(build(
        &data,
        &[
            (0, "La longue nuit"),
            (1, "Bonjour, le monde, comment vas-tu ?"),
            (2, "J'ai dit ⟦g1⟧non⟦/g1⟧.⟦x2⟧Plus jamais."),
            (3, "Attends⟦x1⟧le⟦x2⟧... ⟦x3⟧maintenant"),
        ],
    ));
    let lines: Vec<&str> = out.split('\n').collect();
    assert!(lines.contains(&"Title: La longue nuit"), "{out}");
    assert!(lines.contains(&"Dialogue: 0,0:00:01.00,0:00:04.00,Default,Anna,0,0,0,,Bonjour, le monde, comment vas-tu ?"), "{out}");
    assert!(lines.contains(&"Comment: 0,0:00:01.00,0:00:04.00,Default,,0,0,0,,Do not translate this note"));
    assert!(lines.contains(&"Dialogue: 0,0:00:05.00,0:00:07.50,Default,,0,0,0,,{\\an8}J'ai dit {\\i1}non{\\i0}.\\NPlus jamais."), "{out}");
    assert!(lines.contains(&"Dialogue: 0,0:00:08.00,0:00:09.00,Default,,0,0,0,,{\\pos(400,570)}"));
    assert!(lines.contains(&"Dialogue: 1,0:00:10.00,0:00:11.00,Default,,0,0,0,,{\\p1}m 0 0 l 100 0 100 100 0 100{\\p0}"));
    assert!(lines.contains(&"Dialogue: 0,0:00:12.00,0:00:13.00,Default,,0,0,0,,Attends\\hle\\n... {fix timing}maintenant\\N"), "{out}");
    assert!(lines.contains(&"[V4+ Styles]") && lines.last() == Some(&""), "{out}");
    // re-parse: same unit count, same token shape
    let again = units(out.as_bytes());
    assert_eq!(again.len(), 4);
    assert_eq!(again[2], "J'ai dit ⟦g1⟧non⟦/g1⟧.⟦x2⟧Plus jamais.");
}

#[test]
fn translation_edge_cases() {
    let data = b"[Events]\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,One {\\b1}two{\\b0} three\n";
    // a real newline in the translation becomes \N; unknown markers are dropped
    assert_eq!(units(data), vec!["One ⟦g1⟧two⟦/g1⟧ three"]);
    let out = s(build(data, &[(0, "Un ⟦g1⟧deux⟦/g1⟧\ntrois⟦x9⟧⟦g7⟧")]));
    assert!(out.ends_with(",,Un {\\b1}deux{\\b0}\\Ntrois\n"), "{out}");
    // a Title translation never gets a line break
    let t = b"[Script Info]\nTitle: A\n";
    assert_eq!(build(t, &[(0, "B\nC")]), b"[Script Info]\nTitle: B C\n");
    // <untitled> and blank titles are not units; Title outside Script Info is not either
    for raw in [&b"[Script Info]\nTitle: <untitled>\n"[..], b"[Script Info]\nTitle:\n", b"[Aegisub Project Garbage]\nTitle: x\n"] {
        assert!(extract(raw).unwrap().units.is_empty(), "{raw:?}");
    }
}

#[test]
fn style_switch_pairs_680() {
    let unit = |text: &str| units(format!("{HEAD}{text}\n").as_bytes());
    let bld = |text: &str, tr: &str| {
        let out = s(build(format!("{HEAD}{text}\n").as_bytes(), &[(0, tr)]));
        out.split("0,0,0,,").nth(1).unwrap().trim_end_matches('\n').to_string()
    };
    assert_eq!(unit("Account {\\i1}settings{\\i0}"), vec!["Account ⟦g1⟧settings⟦/g1⟧"]);
    assert_eq!(bld("Account {\\i1}settings{\\i0}", "⟦g1⟧Paramètres⟦/g1⟧ du compte"), "{\\i1}Paramètres{\\i0} du compte");
    assert_eq!(unit("{\\an8}{\\b1}Account{\\b0} settings"), vec!["⟦g1⟧Account⟦/g1⟧ settings"]);
    assert_eq!(bld("{\\an8}{\\b1}Account{\\b0} settings", "Paramètres du ⟦g1⟧compte⟦/g1⟧"), "{\\an8}Paramètres du {\\b1}compte{\\b0}");
    assert_eq!(unit("{\\an8}{\\i1}Whole line{\\i0}"), vec!["Whole line"]);
    assert_eq!(bld("{\\an8}{\\i1}Whole line{\\i0}", "Ligne"), "{\\an8}{\\i1}Ligne{\\i0}");
    assert_eq!(unit("{\\b1}a {\\i1}b{\\r} c"), vec!["⟦g1⟧a ⟦g2⟧b⟦/g2⟧⟦/g1⟧ c"]);
    assert_eq!(bld("{\\b1}a {\\i1}b{\\r} c", "⟦g2⟧B⟦/g2⟧ ⟦g1⟧A⟦/g1⟧ C"), "{\\i1}B{\\i0} {\\b1}A{\\r} C");
    let src = "Say {\\i1}very {\\b1}{\\c&H0000FF&}loud{\\r} now";
    assert_eq!(unit(src), vec!["Say ⟦g1⟧very ⟦g2⟧⟦x3⟧loud⟦/g2⟧⟦/g1⟧ now"]);
    let out = bld(src, "Dis ⟦g1⟧très ⟦g2⟧⟦x3⟧fort⟦/g2⟧⟦/g1⟧ maintenant");
    assert!(out.ends_with("fort{\\b0}{\\r} maintenant"), "{out}");
    assert_eq!(unit("x {\\b1}a{\\i1}b{\\b0}c{\\i0} d"), vec!["x ⟦g1⟧a⟦x2⟧b⟦/g1⟧c⟦x3⟧ d"]);
    assert_eq!(bld("x {\\b1}a{\\b0} y", "X Y ⟦g1⟧⟦/g1⟧"), "X Y ");
    assert_eq!(bld("x {\\b1}a{\\b0} y", "X ⟦/g1⟧Y ⟦g1⟧A"), "X Y {\\b1}A{\\b0}");
}

#[test]
fn custom_format_and_ssa() {
    let ssa = b"[Script Info]\nScriptType: v4.00\n\n[Events]\n\
        Format: Marked, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n\
        Dialogue: Marked=0,0:00:01.00,0:00:02.00,*Default,NTP,0000,0000,0000,!Effect,Hi, you\n";
    assert_eq!(units(ssa), vec!["Hi, you"]);
    let short = b"[Events]\nFormat: Start, End, Text\nDialogue: 0:00:01.00,0:00:02.00,Short, form, text\n";
    assert_eq!(units(short), vec!["Short, form, text"]);
    let out = s(build(short, &[(0, "Forme, courte")]));
    assert!(out.ends_with("Dialogue: 0:00:01.00,0:00:02.00,Forme, courte\n"), "{out}");
    // Text not last in Format: the lines are left alone rather than guessed at
    let odd = b"[Events]\nFormat: Text, Start\nDialogue: Hi,0:00:01.00\n";
    assert!(extract(odd).unwrap().units.is_empty());
    // too few fields: a malformed line is copied verbatim
    let bad = b"[Events]\nDialogue: 0,0:00:01.00,Hello\n";
    assert!(extract(bad).unwrap().units.is_empty());
    assert_identity(bad);
}

#[test]
fn encodings() {
    let cp = {
        let (b, _, _) = bilingua_model::encoding_rs::WINDOWS_1252.encode("[Events]\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Café crème\n");
        b.into_owned()
    };
    let doc = extract(&cp).unwrap();
    assert_eq!(units(&cp), vec!["Café crème"]);
    assert!(matches!(&doc.skeleton, Skeleton::Text { encoding, .. } if encoding.starts_with("windows-1252")));
    // LocOS converts to UTF-8; Bilingua keeps the code page by default and converts on request
    let out = build_locos(&cp, &[(0, "Kaffee")]);
    assert!(s(out).ends_with(",,Kaffee\n"));
    let kept = build(&cp, &[(0, "Kaffee")]);
    assert!(kept.starts_with(b"[Events]") && kept.ends_with(b",,Kaffee\n"));
    let kept2 = build(&cp, &[(0, "Café crème")]);
    assert_eq!(kept2, cp);
    // UTF-16 with BOM
    let mut u16: Vec<u8> = vec![0xFF, 0xFE];
    for c in "[Events]\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Grüße\n".encode_utf16() {
        u16.extend_from_slice(&c.to_le_bytes());
    }
    assert_eq!(units(&u16), vec!["Grüße"]);
    assert_identity(&u16); // untouched = as uploaded
    let built = build_locos(&u16, &[(0, "Grüße!")]);
    // LocOS writes UTF-8 with a BOM here; Bilingua's UTF-8 option drops a UTF-16 BOM (model decision)
    assert!(s(built).ends_with(",,Grüße!\n"));
    let kept16 = build(&u16, &[(0, "Grüße!")]);
    assert!(kept16.starts_with(&[0xFF, 0xFE]) && kept16.len() == u16.len() + 2);
    // a binary upload is refused
    let bin: Vec<u8> = b"\x00\x01\x02\x81\x8d\x8f".iter().cycle().take(300).copied().collect();
    assert!(extract(&bin).is_err());
}

#[test]
fn hostile_caps() {
    let long = "x".repeat(100_000 + 10);
    let data = format!("{HEAD}{long}\n");
    assert!(matches!(extract(data.as_bytes()), Err(Error::Limit(_))), "an over-long Text field must be refused");
    let small = ExtractOptions { limits: Some(Limits { max_units: 3, max_lines: 60, ..Limits::default() }), ..Default::default() };
    let many = format!("[Events]\n{}", "Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Hi\n".repeat(5));
    assert!(matches!(extract_with(many.as_bytes(), &small), Err(Error::Limit(_))), "more units than the cap");
    assert!(matches!(extract_with(&[b'\n'; 70], &small), Err(Error::Limit(_))), "the line budget refuses blank lines");
    // an unclosed brace is literal text
    let weird = b"[Events]\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Hi {there\n";
    assert_eq!(units(weird), vec!["Hi {there"]);
    assert_identity(weird);
}

/// The Python case drives the API and the CLI; here the same document goes through extract, a token-keeping mock
/// translation and merge, with the same assertions on the download.
#[test]
fn pipeline_mock_translate() {
    let data = ass().into_bytes();
    let mut doc = AssFilter.extract(&data, &ExtractOptions { target_lang: Some("fr-FR".into()), ..Default::default() }).unwrap();
    let srcs: Vec<String> = doc.units.iter().map(|u| bilingua_model::locos::to_locos_text(&u.source()).0).collect();
    assert!(srcs.iter().any(|t| t.contains("⟦x1⟧")), "{srcs:?}");
    assert!(!srcs.iter().any(|t| t.contains("Do not translate")), "{srcs:?}");
    let targets: Vec<(String, Vec<Inline>)> = doc
        .units
        .iter()
        .map(|u| {
            let t = u
                .source()
                .into_iter()
                .map(|i| match i {
                    Inline::Text(t) => Inline::Text(format!("[fr] {t}")),
                    tag => tag,
                })
                .collect();
            (u.segments[0].id.clone(), t)
        })
        .collect();
    doc.set_targets(targets).unwrap();
    let out = s(AssFilter.merge_with(&doc, &MergeOptions::locos()).unwrap());
    assert!(out.contains("Comment: 0,0:00:01.00,0:00:04.00,Default,,0,0,0,,Do not translate this note"), "{out}");
    assert!(out.contains("{\\an8}") && out.contains("{\\i1}") && out.contains("{\\i0}") && out.contains("\\N"), "{out}");
    assert!(!out.contains('⟦') && !out.contains('⟧'), "{out}");
    assert!(out.contains("[V4+ Styles]") && out.contains("Dialogue: 1,0:00:10.00"), "{out}");
    assert!(out.contains("Language: fr"), "{out}");
    assert!(out.contains("[fr] Hello, world, how are you?") && out.contains("Title: [fr] The Long Night"), "{out}");
}
